const D = { energy: .58, scale: 1, speed: 1, density: .55, tilt: .35, bridge: .45, hue: 34, x: .47, y: .52, style: 'white_light', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A sunspot, in white light ------------------------------------------------------------
// The photosphere is the top of a convection zone, so it is tiled with GRANULES: hot gas
// rises in the bright cell interiors, cools, and sinks in the dark intergranular lanes.
// Here that is an additively-weighted Voronoi over drifting feature points — a granule's
// weight IS its brightness, so a young hot granule pushes its lanes outward and an old one
// is squeezed away by its neighbours. Nothing converges: every cell runs its own life clock
// at its own period, so the field boils forever.
// Where a rope of ~3 kG field punches through, convection is throttled. That patch cannot
// carry its heat, cools ~1500 K below its surroundings and goes dark: the UMBRA, ~20% as
// bright as the photosphere, stippled with umbral dots where convection still fights through,
// sometimes cut in two by a light bridge. Around it the field leans over and the PENUMBRA
// forms — filaments laid along the near-horizontal field, each a bright body with a DARK CORE
// running its length, and along each the Evershed flow carries brightness outward at ~4 km/s.
// Every filament draws its own Evershed rate from the hash, so the ensemble never re-phases.
// Near the limb the spot is foreshortened (P.tilt) and the plate is limb-darkened.
// ------------------------------------------------------------------------------------------

const TAU = 6.283185307;
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(64, Math.round(BW * height / width));
const NC = BW * BH;

if (!S.g || S.key !== width + 'x' + height) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1);
  S.key = width + 'x' + height;
  S.GR = new Float32Array(NC);
  S.grainKey = null;
}
const g = S.g;

const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };
const fr2 = (i, j) => { const s = Math.sin(i * 127.1 + j * 311.7 + sd * 74.77) * 43758.5453; return s - Math.floor(s); };

// static per-pixel grain (photospheric speckle + plate grain) — built once per size/seed
if (S.grainKey !== S.key + ':' + sd) {
  S.grainKey = S.key + ':' + sd;
  for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
    const a = fr2(i * 2.13 + 3.1, j * 5.71 + 1.7);
    const b = fr2(Math.floor(i / 2) * 7.3 + 11, Math.floor(j / 2) * 3.9 + 5);
    S.GR[j * BW + i] = a * 0.62 + b * 0.38;
  }
}
const GR = S.GR;

// real-time clock, tolerant of t0 resets
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dtr = K.t - S.lastT; S.lastT = K.t;
dtr = dtr < 0 ? 0 : (dtr > 0.06 ? 0.06 : dtr);
if (S.T == null) S.T = 0;
S.T += dtr * (0.25 + P.speed * 0.9);
const ts = S.T;
const en = Math.min(1, Math.max(0, P.energy));
const scl = Math.max(0.4, P.scale);
const style = P.style;

// incommensurate real-time drift floor — the plate never sits still
const dr1 = Math.sin(K.t * 0.061) * 0.9 + Math.sin(K.t * 0.143 + 1.7) * 0.5 + Math.sin(K.t * 0.229) * 0.32;
const dr2 = Math.sin(K.t * 0.083 + 2.1) * 0.9 + Math.sin(K.t * 0.187 + 0.4) * 0.46;

const L = BW / BH;                       // field is [0,L] x [0,1], isotropic in pixels

// ---- granule feature-point table (rebuilt every frame; <=900 cells, trivial) ----
const cs0 = (0.050 + 0.030 * (1 - Math.min(1, P.density))) * Math.pow(scl, 0.5);
let NGX = Math.max(3, Math.round(L / cs0)), NGY = Math.max(3, Math.round(1 / cs0));
if (NGX * NGY > 900) { const k = Math.sqrt(900 / (NGX * NGY)); NGX = Math.max(3, Math.floor(NGX * k)); NGY = Math.max(3, Math.floor(NGY * k)); }
const csx = L / NGX, csy = 1 / NGY, csm = (csx + csy) * 0.5;
const NG = NGX * NGY;
if (!S.PX) { S.PX = new Float32Array(1024); S.PY = new Float32Array(1024); S.PB = new Float32Array(1024); S.PW = new Float32Array(1024); }
const PX = S.PX, PY = S.PY, PB = S.PB, PW = S.PW;
for (let cy = 0; cy < NGY; cy++) for (let cx = 0; cx < NGX; cx++) {
  const c = cy * NGX + cx;
  const j1 = fr2(cx * 3.1 + 1.3, cy * 7.7 + 2.9), j2 = fr2(cx * 5.9 + 9.1, cy * 11.3 + 4.7), j3 = fr2(cx * 13.7 + 3.3, cy * 2.1 + 8.9);
  const wob = ts * 0.040;
  PX[c] = (cx + 0.5 + (j1 - 0.5) * 0.66 + 0.15 * Math.sin(wob * 1.13 + j1 * TAU)) * csx;
  PY[c] = (cy + 0.5 + (j2 - 0.5) * 0.66 + 0.15 * Math.sin(wob * 0.79 + j2 * TAU + 1.1)) * csy;
  const life = 52 + j3 * 40;                                   // s — every granule its own period
  const ph = (ts / life + j1 * 3.71 + j2 * 2.29) % 1;
  const b = 0.5 + 0.5 * Math.sin(ph * TAU);                    // rise, brighten, fade, be replaced
  PB[c] = b;
  PW[c] = (b - 0.5) * csm * 0.30;                              // hot granules push their lanes out
}

// ---- spot geometry ----
const tl = Math.min(1, Math.max(0, P.tilt));
const cosT = 1 - tl * 0.72;                                    // foreshortening toward the limb
const spx = Math.min(1, Math.max(0, P.x)) * L + 0.010 * L * dr1;
const spy = Math.min(1, Math.max(0, P.y)) + 0.008 * dr2;
const rU = 0.072 * scl * (0.85 + en * 0.30);
const rP = rU * (2.35 + 0.35 * Math.sin(ts * 0.037));          // penumbra/umbra ratio breathes
const nf = Math.round(30 + P.density * 74);
const kR = 13 + P.density * 11;
const vE = 0.55 + en * 1.05;
const brA = Math.min(1, Math.max(0, P.bridge));
const brAng = 0.7 + 0.16 * dr1;
const brW = rU * (0.10 + brA * 0.30);
const nDots = Math.round(8 + en * 22);
const superF = style === 'halpha' ? 1 : 0;
const pol = fr(1) < 0.5 ? -1 : 1;                              // this spot's leading polarity
const gCon = (0.55 + en * 0.75) * (style === 'halpha' ? 0.42 : 1) * (style === 'magnetogram' ? 0.14 : 1);
const rOut = rP * (1.9 + superF * 2.2);

// ---- gradient-map endpoints (shadow / mid / highlight) ----
const h2rgb = (h, s, v) => {
  h = (((h % 360) + 360) % 360) / 60;
  const c = v * s, x = c * (1 - Math.abs(h % 2 - 1)), m = v - c;
  if (h < 1) return [c + m, x + m, m];
  if (h < 2) return [x + m, c + m, m];
  if (h < 3) return [m, c + m, x + m];
  if (h < 4) return [m, x + m, c + m];
  if (h < 5) return [x + m, m, c + m];
  return [c + m, m, x + m];
};
let c0, cM, cH;
if (style === 'halpha') { c0 = h2rgb(P.hue - 32, 0.94, 0.035); cM = h2rgb(P.hue - 24, 0.90, 0.40); cH = h2rgb(P.hue - 6, 0.44, 0.94); }
else if (style === 'magnetogram') { c0 = [0.03, 0.03, 0.04]; cM = [0.44, 0.44, 0.45]; cH = [0.95, 0.95, 0.94]; }
else if (style === 'engraved') { c0 = [0.09, 0.075, 0.065]; cM = [0.47, 0.435, 0.39]; cH = [0.84, 0.80, 0.71]; }
else if (style === 'ironbow') { c0 = [0.02, 0.02, 0.14]; cM = [0.60, 0.10, 0.44]; cH = [0.98, 0.90, 0.55]; }
else { c0 = h2rgb(P.hue - 18, 0.80, 0.06); cM = h2rgb(P.hue, 0.66, 0.44); cH = h2rgb(P.hue + 10, 0.22, 0.86); }

const gmap = b => {
  b = b < 0 ? 0 : (b > 1 ? 1 : b);
  if (b < 0.5) { const u = b * 2; return [c0[0] + (cM[0] - c0[0]) * u, c0[1] + (cM[1] - c0[1]) * u, c0[2] + (cM[2] - c0[2]) * u]; }
  const u = (b - 0.5) * 2;
  return [cM[0] + (cH[0] - cM[0]) * u, cM[1] + (cH[1] - cM[1]) * u, cM[2] + (cH[2] - cM[2]) * u];
};

g.loadPixels();
const px = g.pixels;

for (let j = 0; j < BH; j++) {
  const fy = (j + 0.5) / BH;
  for (let i = 0; i < BW; i++) {
    const fx = (i + 0.5) / BH;
    const p = j * BW + i;
    const gr = GR[p];

    // ---------- granulation (additively-weighted Voronoi) ----------
    const gx = Math.floor(fx / csx), gy = Math.floor(fy / csy);
    let d1 = 1e9, d2 = 1e9, c1i = 0;
    for (let oy = -1; oy <= 1; oy++) {
      let cy2 = gy + oy, wy = 0;
      if (cy2 < 0) { cy2 += NGY; wy = -1; } else if (cy2 >= NGY) { cy2 -= NGY; wy = 1; }
      for (let ox = -1; ox <= 1; ox++) {
        let cx2 = gx + ox, wx = 0;
        if (cx2 < 0) { cx2 += NGX; wx = -L; } else if (cx2 >= NGX) { cx2 -= NGX; wx = L; }
        const c = cy2 * NGX + cx2;
        const ddx = PX[c] + wx - fx, ddy = PY[c] + wy - fy;
        const d = Math.sqrt(ddx * ddx + ddy * ddy) - PW[c];
        if (d < d1) { d2 = d1; d1 = d; c1i = c; } else if (d < d2) { d2 = d; }
      }
    }
    let lane = (d2 - d1) / (csm * 0.46);
    lane = lane > 1 ? 1 : lane;
    lane = lane * lane * (3 - 2 * lane);                        // smoothstep: dark lane -> bright interior
    let v = (0.14 + 0.76 * lane) * (0.58 + PB[c1i] * 0.62);     // ~[0.08, 1.08], mean ~0.53
    v = 0.46 + (v - 0.53) * gCon + (gr - 0.5) * 0.09;

    // ---------- the spot ----------
    const ex = (fx - spx) / cosT, ey = fy - spy;
    const r = Math.sqrt(ex * ex + ey * ey);
    let mag = 0;                                               // |B| proxy, for the magnetogram style
    if (r < rOut) {
      const th = Math.atan2(ey, ex);
      const tn = th / TAU + 0.5;
      const fi = Math.floor(tn * nf);
      const fph = fr(fi * 3.17 + 7.3);
      const u = (tn * nf - fi) * 2 - 1;                         // -1..1 across one filament
      const env = 1 - u * u;
      const core = Math.exp(-u * u * 46);                       // the dark core down its middle
      const fb = env * (1 - 0.52 * core * (0.5 + en * 0.5));

      if (r < rU) {
        let umb = 0.075 + gr * 0.05 + 0.025 * Math.sin(fx * 41 + fy * 37 + ts * 0.3);
        for (let q = 0; q < nDots; q++) {
          const q1 = fr(q * 9.13 + 21), q2 = fr(q * 4.71 + 53), q3 = fr(q * 17.3 + 7);
          const dl = 3.2 + q3 * 4.5;
          const dph = (ts / dl + q1 * 5.3) % 1;
          const dR = Math.sqrt(q2) * rU * 0.88;
          const da = q1 * TAU + ts * 0.03 * (q3 - 0.5);
          const ddx = ex - dR * Math.cos(da), ddy = ey - dR * Math.sin(da);
          const dd = ddx * ddx + ddy * ddy;
          const rad = rU * 0.055, r2 = rad * rad;
          if (dd < r2 * 9) umb += Math.exp(-dd / r2) * Math.sin(dph * Math.PI) * (0.28 + en * 0.40);
        }
        const bd = Math.abs(ex * Math.sin(brAng) - ey * Math.cos(brAng));
        if (brA > 0.02 && bd < brW * 2.4) {
          let bm = 1 - bd / (brW * 2.4); bm = bm * bm * (3 - 2 * bm);
          umb += (v * 0.60 + 0.05) * bm * brA;                  // light bridge: surviving convection
        }
        let eu = Math.min(1, (rU - r) / (rU * 0.17)); eu = eu * eu * (3 - 2 * eu);
        v += (umb - v) * eu;
        mag = 1;
      } else if (r < rP) {
        const rr = (r - rU) / (rP - rU);
        const ev = 0.5 + 0.5 * Math.sin(rr * kR - ts * vE * (0.75 + fph * 0.62) + fph * TAU);
        const pen = 0.28 + 0.48 * fb * (0.52 + 0.48 * ev) + 0.10 * rr + gr * 0.045;
        let ep = Math.min(1, (r - rU) / (rP * 0.10)); ep = ep * ep * (3 - 2 * ep);
        let eo = Math.min(1, (rP - r) / (rP * 0.13)); eo = eo * eo * (3 - 2 * eo);
        v += (pen - v) * Math.min(ep, eo);
        mag = (1 - rr) * 0.72;
      } else {
        const q = (r - rP) / (rP * 0.55);
        const ring = Math.exp(-q * q * 2.2);
        v += ring * (0.06 + en * 0.07) * (0.4 + 0.6 * (1 - lane));   // bright ring + faculae in the lanes
        mag = ring * 0.30;
        if (superF > 0) {
          const rs = (r - rP) / (rP * 2.4);
          v += Math.exp(-rs * rs * 1.7) * Math.max(0, fb) *
               (0.5 + 0.5 * Math.sin(rs * 22 - ts * vE * 0.7 * (0.7 + fph * 0.7) + fph * TAU)) * 0.28;
        }
      }
    }

    // ---------- limb darkening + plate vignette ----------
    const lx = fx / L - 0.5, ly = fy - 0.5;
    v *= 1 - tl * 0.30 * (fx / L) - 0.16 * (lx * lx + ly * ly);
    v += 0.03;

    // ---------- style rendering ----------
    let R, G2, B;
    if (style === 'magnetogram') {
      // radically abstracted: forget the light — this is signed line-of-sight field strength.
      // Quiet sun is neutral grey threaded with the churning salt-and-pepper network flux
      // elements that live in the lanes; the spot is one saturated pole; the photosphere
      // simply is not there.
      const netsg = fr2(Math.floor(PX[c1i] * 190) + 3, Math.floor(PY[c1i] * 190) + 9) < 0.5 ? -1 : 1;
      const net = Math.max(0, 1 - lane * 1.35) * (0.10 + PB[c1i] * 0.30) * netsg;
      const cc = gmap(0.5 + (net * 0.55 + mag * 0.52 * pol) * (0.5 + en * 0.9));
      R = cc[0]; G2 = cc[1]; B = cc[2];
    } else if (style === 'engraved') {
      // a 19th-century heliograph plate: tone becomes engraved line, and the burin follows the
      // structure — radial inside the spot, cross-hatched over the quiet photosphere.
      const inSpot = r < rP * 1.05;
      const ang = inSpot ? Math.atan2(ey, ex) : 0.55;
      const sA = Math.sin(ang), cA = Math.cos(ang);
      const ha = 0.5 + 0.5 * Math.sin((i * cA + j * sA) * (inSpot ? 2.6 : 1.5));
      const hb = 0.5 + 0.5 * Math.sin((i * -sA + j * cA) * 1.5);
      const ink = Math.max(0, 1 - v * 1.10);
      const cov = (ha < ink ? 1 : 0) * 0.62 + (hb < ink - 0.42 ? 1 : 0) * 0.38;
      const cc = gmap(0.78 - cov * 0.66 + (gr - 0.5) * 0.06);
      R = cc[0]; G2 = cc[1]; B = cc[2];
    } else {
      const cc = gmap(v);
      R = cc[0]; G2 = cc[1]; B = cc[2];
    }

    // audio rides on top of the baseline, never multiplies it
    const lift = A.rms * 0.10 + K.swell * 0.03;
    R += lift; G2 += lift * 0.93; B += lift * 0.8;

    const o = 4 * p;
    px[o] = R < 0 ? 0 : (R > 1 ? 255 : R * 255);
    px[o + 1] = G2 < 0 ? 0 : (G2 > 1 ? 255 : G2 * 255);
    px[o + 2] = B < 0 ? 0 : (B > 1 ? 255 : B * 255);
    px[o + 3] = 255;
  }
}
